def __call__(self, batch_in):
        if self.input_batch_is_collated:
            batch = batch_in
        else:
            batch, sample_cls = self.collate_batch(batch_in)
            batch_cls = sample_cls.get_batch_sample_class()
            batch = batch_cls(**default_collate(batch))
        if self.batch_kwargs is not None:
            batch_field_names = {f.name for f in fields(Batch)}
            for key, value in self.batch_kwargs.items():
                assert key in batch_field_names
                setattr(batch, key, value)

        if self.batch_transforms is not None:
            for transform in self.batch_transforms:
                batch = transform(batch)

        if self.output_key is not None:
            batch = {self.output_key: batch}
        return batch

def __call__(self, x):
        assert isinstance(x, torch.Tensor)
        if x.ndim == 3:
            # CxHxW
            num_channels = x.shape[0]
            channel_index = 0
        elif x.ndim == 4:
            # TxCxHxW
            num_channels = x.shape[1]
            channel_index = 1
        else:
            raise ValueError(f"Unexpected number of dims {x.ndim}. Expected 3 or 4.")

        assert num_channels == len(
            self.channel_probs
        ), f"channel_probs is {len(self.channel_probs)} but got {num_channels} channels"

        to_drop = [
            np.random.random() < self.channel_probs[c] for c in range(num_channels)
        ]
        if self.tie_channels is not None:
            first_drop = to_drop[self.tie_channels[0]]
            for idx in self.tie_channels[1:]:
                to_drop[idx] = first_drop

        if all(to_drop) and self.all_channel_drop is False:
            # all channels will be dropped, prevent it
            to_drop = [False for _ in range(num_channels)]

        for c in range(num_channels):
            if not to_drop[c]:
                continue
            if channel_index == 0:
                x[c, ...] = self.fill_values[c]
            elif channel_index == 1:
                x[:, c, ...] = self.fill_values[c]
            else:
                raise NotImplementedError()
        return x

def __call__(self, img):
        if self.prob < 1.0 and random.random() > self.prob:
            return img
        magnitude = self.magnitude
        if self.magnitude_std and self.magnitude_std > 0:
            magnitude = random.gauss(magnitude, self.magnitude_std)
        magnitude = min(_MAX_LEVEL, max(0, magnitude))  # clip to valid range
        level_args = (
            self.level_fn(magnitude, self.hparams) if self.level_fn is not None else ()
        )
        return self.aug_fn(img, *level_args, **self.kwargs)

