        path = self._replace_path_prefix(
            self.paths[idx],
            replace_prefix=self.remove_prefix,
            new_prefix=self.new_prefix,
        )
        path = self._replace_path_suffix(
            path, replace_suffix=self.remove_suffix, new_suffix=self.new_suffix
        )
        return path

def run_train(self):
        # loop
        while self.epoch < self.max_epochs:

            outs = self.train_epoch(
                self.train_dataset.get_loader(epoch=int(self.epoch))
            )
            self.logger.log_dict(outs, self.epoch)  # Logged only on rank 0

            # log train to text file.
            if self.distributed_rank == 0:
                with g_pathmgr.open(
                    os.path.join(self.logging_conf.log_dir, "train_stats.json"),
                    "a",
                ) as f:
                    f.write(json.dumps(outs) + "\n")

            # Run val
            if self.epoch % self.val_epoch_freq == 0:
                self.run_val()

            self.epoch += 1
            self.checkpoint_save(self.epoch)

