def state_dict(self, *args, **kwargs):
    self.reset_ema_unets_all_one_device()
    return super().state_dict(*args, **kwargs)

def load_state_dict(self, *args, **kwargs):
    self.reset_ema_unets_all_one_device()
    return super().load_state_dict(*args, **kwargs)

